// Кейс: .qa/tests/monitoring/MON-012.md · план: .qa/e2e-app/specs/app.md (1.9)
// «בדיקת בטיחות»: громкость 0 / ниже 50% → предупреждение в строке «עוצמת צפצוף מקסימלית», «המשך» серая.
// РУЧНОЕ ПРЕДУСЛОВИЕ (Appium громкость не меняет): выставить громкость кнопками и запустить с
//   BANCI_VOLUME=0    — громкость на нуле
//   BANCI_VOLUME=low  — громкость ниже 50% (но не 0)
// Без BANCI_VOLUME тест пропускается. После теста вернуть громкость на максимум (нужно для 1.8 и тревог).
import { by, assert, skip } from '../../lib/appium.mjs';
import { openSafetyCheck, waitEnabled } from '../../lib/banci.mjs';

export const name = 'בדיקת בטיחות: громкость 0 / ниже 50% → «עוצמת הקול כבויה/נמוכה — הגבירו…», «המשך» серая (ручное предусловие BANCI_VOLUME) #e2f5c7 @iphone @app @prod-safe';

const EXPECTED = {
  0: 'עוצמת הקול כבויה — הגבירו את העוצמה בכפתורי הצד ולחצו על «בדיקה חוזרת»',
  low: 'עוצמת הקול נמוכה — הגבירו את העוצמה עד הסוף',
};

export default async function (app) {
  const mode = process.env.BANCI_VOLUME;
  if (!(mode in EXPECTED)) skip('громкость выставляется только вручную: поставить громкость iPhone на 0 (или ниже 50%) и запустить с BANCI_VOLUME=0 (или low)');

  await openSafetyCheck(app);

  // 1. Предупреждение в строке громкости.
  await app.waitFor(by.contains(EXPECTED[mode]), {
    timeout: 20000,
    what: `строка «${EXPECTED[mode]}…» (BANCI_VOLUME=${mode}; если громкость на самом деле другая — выставить и перезапустить)`,
  });
  assert(!(await app.exists(by.contains('השמיעו את צליל הבדיקה ואשרו ששמעתם אותו'))), 'вместо предупреждения нет обычной строки «השמיעו את צליל הבדיקה…»');

  // 2. «המשך» серая.
  const next = await app.waitFor(by.exact('המשך', 'Button'), { what: '«המשך»' });
  await waitEnabled(next, false, { timeout: 5000, what: '«המשך» при низкой громкости' });

  await app.restart();
}
